INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>مقدمة في زراعة البصل بنظام النطاق النقطي</h2>\n<p>يعد البصل من الخضروات الأساسية في التغذية البشرية، وله أهمية كبيرة في المناطق الباردة وشبه الباردة. من الناحية التقنية، البصل نبات ذو جذور سطحية وعريضة، ولا يتحمل عمومًا الري بالغمر. في السنوات الأخيرة، تغيرتแนวทาง العالمية في زراعة البصل من الري المطري والغمر إلى <strong>الري النقطي عبر النطاقات</strong> لم يعد هذا التغيير بسبب ترشيد استهلاك المياه فحسب، بل يهدف بشكل رئيسي إلى خلق بيئة متجانسة لنمو الجذور وتقليل الأمراض الفطرية، حيث أن المصدر الرئيسي لها هو الرطوبة الزائدة وغير المناسبة حول البصلة (الدرن). من خلال توزيع الماء بشكل نقطي ومنضبط، يحافظ الري النقطي عبر النطاقات على رطوبة التربة في نطاق الجذور، مما يمنع الجفاف والتقلب في بلوّة التربة.</p>\n<p>في هذا القسم من المقال، سننظر في جميع تحديات العناية بالبصل باستخدام النطاق النقطي، حتى مع معرفة التفاصيل التقنية، تستطيع اتخاذ قرارات أفضل لمزرعتك. استخدام هذه التقنية يتطلب معرفة فنية؛ لأن خطأً واحدًا في التثبيت أو ضبط الضغط قد يؤدي إلى تعفن البصلة أو تقليل حجم المنتج النهائي.</p>\n\n<h2>المعلمات الفنية لاختيار النطاق النقطي للبصل</h2>\n<p>اختيار النوع المناسب من النطاق النقطي هو الخطوة الأولى في العناية الصحيحة بالبصل. على عكس الطماطم والخيار اللذين لهما سيقان طويلة، يعد البصل محصولًا له مسافات زراعة كثيفة. لذلك، عادةً ما تتراوح المسافة بين صفوف الزراعة (مسافات الصفوف) في زراعة البصل بين 25 و30 سنتيمتر. هذا يجعل اختيار النطاق النقطي بقطر مناسب ومسافة بين الثقوب أمرًا بالغ الأهمية.</p>\n<ul>\n<li><strong>قطر النطاق:</strong> بالنسبة للبصل، تُستخدم عادةً شرائح بعرض 16 أو 19 مم. الشرائح الأسمك مناسبة أكثر للسوائل اللزجة، لكن للبصل الذي يحتاج إلى امتصاص هادئ، فإن الشرائح القياسية كافية.</li>\n<li><strong>مسافة البعد بين المصبّات (Emitter Spacing):</strong> عادةً ما يُراعى 20 أو 30 سم. يجب أن تتطابق هذه المسافة مع مسافة مسارات الزراعة لضمان وصول الماء إلى مركز المسار بالضبط.</li>\n<li><strong>هيكل الشريط:</strong> يُوصى باستخدام الشرائح ذات القنوات (Channeled) للتربة الرملية، والشرائح البولي مريكية الناعمة (Laminar) للتربة ذات الحبيبات الناعمة. بالنظر إلى تركيب تربة حقول البصل التي تكون غالباً رملية طينية، فإن الشرائح ذات القنوات تمنع انسداد الفتحات بشكل أفضل.</li>\n</ul>\n<p>يجب الانتباه إلى أنه يجب إزالة شريط T-rip بعد انتهاء دورة زراعة البصل من الحقل وتخزينه. سيتم شرح هذه النقطة بالتفصيل في الأقسام التالية المتعلقة بصيانة المعدات. ولكن لفهم أفضل لكيفية تأثير نظام الري على محاصيل الخضروات الأخرى ذات الجذور السطحية، يمكن أن يُوضّح القراءة عن مقال <a href="https://navar-abyari.ir/comprehensive-guide-cucumber-drip-irrigation-tajik/">الدليل الشامل لري الخيار بالتنقيط</a> الوجهات الفنية الشائعة بين الخيار والبصل، حيث إن كليهما يحتاج إلى رطوبة منتظمة.</p>\n<h2>تخطيط الري وإدارة رطوبة التربة</h2>\n<p>تحتاج البصل إلى كميات مختلفة من الماء في مراحل نموها المختلفة. يتطلب العناية المناسبة بالبصل باستخدام شريط التنقيط فهم هذه المراحل:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-پیاز-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری پیاز با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>عناية وصيانة شريط التنقيط للمحاصيل البصل</figcaption></figure>\n<ol>\n<li><strong>مرحلة الإنبات والنمو الابتدائي:</strong> في الأسبوعين الأولين إلى الثالث بعد الزراعة، تكون النباتات شابة والجذور ضعيفة. يجب إجراء الري بحجم منخفض وبتكرار مرتفع (كل يوم إلى يومين). يجب تقليل ضغط شريط التنقيط إلى أدنى حد في هذه المرحلة لمنع انجراف البذور أو الشتلات.</li>\n<li><strong>مرحلة النمو الخضبي:</strong> مع زيادة مساحة الأوراق، تزيد الحاجة إلى الماء. في هذه المرحلة، يجب الحفاظ على رطوبة التربة عند 60 إلى 70٪ من سعة الحقل. ي facilitit الاستخدام من شريط التنقيط في هذه الفترة إمكانية التسميد الحيوي (Fertigation) المتزامن، وهو أمر ضروري لتغذية البصل.</li>\n<li><strong>مرحلة تكوّن الثمار:</strong> هذه المرحلة هي الأكثر حساسية من حيث الجودة. قد يؤدي نقص مفاجئ في الماء إلى تقليل حجم البصل. وعلى العكس من ذلك، فإن الرطوبة الزائدة تسبب نمو الأوراق وبقاء الدوّار (البصلة) صغيراً. يُنصح بتقليل نسبة الري تدريجياً بنسبة 50% تقريباً خلال الأسبوعين الأخيرين قبل الحصاد، لتصبح قشرة البصل أكثر صلابة ولتزداد مدة حفظه بعد الجني.</li>\n</ol>\n<p>إدارة الضغط خلف خط التنقيط لها أهمية خاصة أيضاً. نظراً لجذور البصل الدقيقة، فإنه لا يتحمل الري الشديد. لذلك، لا يجب أن يتجاوز الضغط التشغيلي ما بين 1 إلى 1.5 بار. استخدام منظمات ضغط مناسبة في رؤوس الخطوط الرئيسية يضمن توزيع الماء بشكل متساوٍ على طول خط التنقيط بالكامل.</p>\n<h2>تحسين التربة والوقاية من التلوث</h2>\n<p>من الفوائد الرئيسية لتقنية التنقيط، إمكانية إبقاء سطح التربة جافاً بين الصفوف. هذه الميزة تجعل زراعة البصل بالتنقيط أسهل من حيث تقليل الأمراض الفطرية. فالفطريات مثل <em>Botrytis</em> و <em>Sclerotium</em> التي تسبب تعفن البصل، تنمو بسرعة في البيئة الرطبة المحيطية. مع الري بالتنقيط، يكون منطقة الجذور فقط هي المبللة بينما يبقى سطح التربة جافاً.</p>\n<p>ومع ذلك، قد توفر هذه الحالة فرصة لبعض الآفات. قد تتحرك بعض الآفات الحشرية التي تعيش في التربة نحو خط التنقيط بحثاً عن الرطوبة. للتعامل مع هذه المشكلة، يُنصح باستخدام مهاد بلاستيكي أو تغطية بلاستيكية خفيفة لصفوف البصل. بالإضافة إلى ذلك، يمكن تحسين تصريف التربة عن طريق إضافة الكمبوست أو الورميكوليت. إذا كان هناك زراعة لحبوب البقوليات مثل الحمص في الحقول المجاورة، فإن إدارة المخلفات النباتية تصبح مهمة أيضاً. لمعرفة ظروف زراعة بقوليات أخرى قد تكون ضمن دورة المحاصيل لديك، يمكنك الاطلاع على المقال <a href="https://navar-abyari.ir/mung-bean-seed-rate-per-hectare-afghanistan/">مقدار بذور الفول المسجل للhectar الواحد</a> راقب كونوا لضمان التخصيص المناسب في الحقول المشتركة.</p>\n<h3>إدارة التسميد من خلال أنبوب التنقيط</h3>\n<p>التسميد الفوري المباشر للجذور هو من أفضل الطرق في أنظمة التنقيط. البصل حساس للنيتروجين والبوتاسيوم والكبريت. في نظام التنقيط، يمكن حقن الأسمدة القابلة للذوبان في الماء بجرعات صغيرة ومتكررة. هذا يقلل من الملوحة حول الجذور مقارنة بالري بالغمر. النقطة الرئيسية في العناية بالبصل بالتنقيط هي منع ترسب أملاح الأسمدة في الفواصل الوسطى؛ لذلك، لا تنسوا دورة غسيل (Flush) بعد كل دورة تسميد.</p>\n\n<h2>الآفات والأمراض الشائعة وسبل المكافحة</h2>\n<p>كل نظام ري يأتي بنظام بيئي خاص به. فيما يتعلق بنظام التنقيط، الخطر الرئيسي <strong>انسداد الفتحات (Clogging)</strong> وهو الانسداد الذي يمكن أن يكون فيزيائياً (جسيمات دقيقة) أو بيولوجياً (طحالب وبكتيريا). لمنع هذه المشكلة، يجب غسيل نظام معالجة المياه (فلتر شبكي أو قرصي) شهرياً.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-پیاز-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری پیاز با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>crop drip tape maintenance care پیاز</figcaption></figure>\n<p>أمراض الفطرية التربة في البصل، مثل التعفن الأبيض (Sclerotinia)، تتكثر عندما لا تكون هناك تصريف مناسب. على الرغم من أن الري بالتنقيط يساعد، إلا أنه في التربة الثقيلة أو اللزجة، يجب استخدام التصريف الرأسي (البرك). كما أن بعض الآفات، مثل العث (Thrips) الذي يكون ضار جداً للبصل، تنمو في ظروف بيئية معينة. على الرغم من أن التحكم فيها يتم بالمبيدات الكيميائية، إلا أن تقليل الإجهاد الجذري بالري المنتظم يزيد من مقاومة النبات للتلوث. لفهم أفضل لدورة الأكل للحشرات في الأنظمة الحديثة، قد يكون من المفيد دراسة مصدر مثل <a href="https://navar-abyari.ir/harisnoqi-i-juvi-shashparra-dar-yak-hektor/">دليل مكافحة البعوضة التربة والآفات ذات الست أرجل</a> إذ أن بعض الآفات التربة مشتركة بين هذين النظامين.</p>\n<h2>نقاط عملية لصيانة النطاق الفيزيائي للشريط</h2>\n<p>الشريط بالتنقيط عادة يكون للاستخدام مرة واحدة، ولكن في الأنظمة متعددة السنوات، يتم صيانة الشريط من خلال تدميره وإغلاقه وفتحه للصول القادمة. البصل محصول يستخدم عادة شرائط استهلاكية له، لأن الشريط يدفن داخل التربة وبعد حصاد البصل، يُخرج الشريط ويجمع. إذا أردت استخدام الشريط نفسه للزراعة التالية، يجب عليك اتباع الخطوات التالية:</p>\n<ul>\n<li><strong>غسل الماء (Flush):</strong> قبل إغلاق المصادر، يتم تمرير الماء بضغط مناسب ودرجة حرارة مناسبة عبر الشريط لغسل الرواسب الداخلية.</li>\n<li><strong>تنظيف: </strong>يجب غمس الحزام وغسله في محلول تانر مخفف أو حمضي (حسب نوع الرواسب).</li>\n<li><strong>التجفيف: </strong>يجب تجفيف الحزام في الظل. التعرض لأشعة الشمس المباشرة سيتلف بوليمر الحزام.</li>\n<li><strong>الطي والربط: </strong>يجب طي الأحزمة على شكل لفات منتظمة بضغط منخفض حتى لا تتعرض الدرزات المثقبة للضغط ولا تسد الفتحات.</li>\n</ul>\n<p>تذكر أن البصل محصول ينمو بسرعة. لذلك، إذا كانت شريطتك ذات غرس سنوي متعدد، تأكد من حصادها من الموسم السابق. عدم الحصاد وتربس الحزام من الأسباب الرئيسية لانخفاض المحصول في المواسم اللاحقة. هذه النقطة حاسمة جداً في زراعة البصل بنظام الشريط.</p>\n<h2>مقارنة مع الري تحت السطحي</h2>\n<p>يستخدم بعض المزارعين نظام الري تحت السطحي لتقليل التبخر. هل هذا النظام أفضل للبصل؟ يوصل الري تحت السطحي الماء مباشرة إلى طبقة الجذور ويقلل التبخر إلى حد الصفر. ومع ذلك، البصل محصول بصلي يثبت على سطح التربة. قد يسبب توصيل الماء عبر أنبوب تحت سطحي تغيراً في رطوبة التربة حول البصلة وتفاقم تعفنها وقت الحصاد. من ناحية أخرى، يمنحك شريط الري السطحي تحكماً أكبر على مستوى البصلة. للمقارنة الأدق، يمكنك قراءة المقال <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%b2%db%8c%d8%b1-%d8%b3%d8%b7%d8%ad%db%8c-%da%af%db%8c%d8%a7%d9%87%d8%a7%d9%86/">الري بالتنقيط للنباتات</a> اقرأوا لتعرفوا لماذا هذه الطريقة غير شائعة عادةً للبطاطس بقدر ما هو الحال مع شريط الري بالتنقيط.</p>\n<h2>الأسئلة الشائعة</h2>\n<h3>هل يسبب شريط الري بالتنقيط تعفن البصل؟</h3>\n<p>لا، ما لم يصل محتوى الرطوبة في التربة إلى أكثر من 90٪ من سعة التربة بحد أقصى. تقلب مستوى الرطوبة الناتج عن الري بالتنقيط المتكرر وغير الكثيف، في الواقع، يمنع التعفن الفطري. يحدث التعفن عندما يؤثر الري بالغمر والممتد على البصلة.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-پیاز-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری پیاز با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>صيانة وإجراءات العناية بشريط الري بالتنقيط للبصل</figcaption></figure>\n<h3>ما أفضل وقت لجمع محصول البصل باستخدام نظام الري بالتنقيط؟</h3>\n<p>يعتمد وقت الجمع على الظروف المحلية، ولكن عادةً يكون عندما تصل نسبة الأصفر وسقوط الأوراق (الاستلقاء) من 70 إلى 80٪. في نظام الري بالتنقيط، يجب إيقاف الري أو تقليله بشكل كبير لمدة 10 إلى 15 يومًا قبل الجمع حتى تجف جلدات البصل وتصبح مقاومة.</p>\n<h3>ما هي المسافة المثالية لنظام الري بالتنقيط من بصل؟</h3>\n<p>عادةً ما يُوضع خيط الري بالتنقيط على مسافة تتراوح بين 10 و15 سنتيمتراً من منتصف الساق (على بعد 2 إلى 3 سنتيمترات من حافة الساق المخصب). يمكن أن تتغير هذه المسافة حسب نوع التربة. في الأراضي طينية الغيار، يُفضل وضع الخيط أقرب إلى بصل، بينما في الأراضي الرملية، يُفضَّل وضعه أبعد قليلاً حتى يبقى الرطوبة ضمن منطقة الجذور.</p>\n\n<h2>الخلاصة والتوصيات النهائية</h2>\n<p>استخدام نظام الري بالتنقيط في زراعة البصل يمثل استثماراً طويل الأمد لزيادة الجودة وخفض التكاليف التشغيلية. العناية بالبصل مع الري بالتنقيط تتطلب دقة في ثلاث نقاط رئيسية: أولاً، ضبط الضغط والتدفق بشكل صحيح؛ ثانياً، إدارة الأسمدة والرطوبة بدقة؛ ثالثاً، الصيانة الجسدية للتوصيلات بعد الجني. باتباع هذه المبادئ، يمكنكم تحقيق إنتاجية تتكافأ مع الري التقليدي أو تتفوق عليه، حتى في ظروف قلة المياه.</p>\n<p>لمزارع يسعون لتوسعة مزارعهم، من المهم أيضاً النظر في دورانية زراعية استراتيجية. يمكن المزج بين البصل وكثير من المحاصيل الأخرى ضمن دورة زراعية سنوية. فهم أداء المحاصيل الأخرى في مزارعكم يساعدكم على التخطيط الأفضل. على سبيل المثال، إذا تضمنت مزارعكم زراعة بقوليات أخرى، فإن قراءة تقرير عن محصول اللوبياء الخضراء في الهكتار الواحد سيساعدكم على معرفة كيفية تحسين إنتاجية المحصول التالي في دورانت الزرع باستخدام نفس نظام الري الأمثل. النجاح في الزراعة الحديثة هو مزج العلم مع الخبرة واستخدام الحكيم للتكنولوجيا.</p>','حفظ البطاطا بالنوافير: نقاط أساسية ومبادئ الري بالتنقيط','يُعدّ البصل من المنتجات الزراعية الهامة ذات الحساسية العالية للرطوبة والظروف البيئية. يمكن أن يوفر نظام الري بالتنقيط بالحزام حلاً فعالاً لإدارة المياه بشكل الأمثل وزيادة الغلة. في هذا المقال، سنتناول النقاط الرئيسية للعناية بالبصل باستخدام نظام الري بالحزام.','publish','closed','closed','preserving-potatoes-with-tips-and-drip-irrigation',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
