INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима бар карзи шибиҳо бо системаи қаторбандии доимӣ</h2>\n<p>Шибиҳо яке аз сабзавоти асосӣ дар ғизои одамон мебошанд, ки дар минтаҳаҳои хунук ва нимхунук аҳамияти баланд доранд. Аз нигоҳи фаннӣ, шибиҳо ноъирандае буда, решаҳои сатҳӣ ва паҳн доранд ва ба тақрибан қарордоии абророниро саҳбук намебароранд. Дар солҳои охир, رویкарди ҷаҳонӣ дар карзи шибиҳо аз ороиши боронӣ ва қарордоӣ ба сӯи <strong>қаторбандии қатраӣ</strong> тағйир ёфтааст. Ин тағйират фақат барои таҳсилоти истеъмолоти об нест; балки мақсади асосии он таъмини муҳити якхела барои рушди решаҳо ва кам кардани бемориҳои қомишии мебошад, ки манбаи асосии онҳо рутубати зиёд ва номаъмул дар атрофи болоб (шибиҳо) аст. Қаторбандии қатраӣ бо тақсимоти нуқтагӣ ва назоратшудаи об, амиқии рутубатро дар ҳудуди решаҳо нигоҳ медорад ва аз хушкшавӣ ва бознгардонишавии ноустувор пешгирӣ менамояд.</p>\n<p>Дар ин қисмати мақола мо ба таҳқиқи тамоми чаллҳои нигоҳдории шибиҳо бо қаторбандӣ мепардем, то бо шиносоии шумо бо тафсилоти фаннӣ, корҳо мафҳумро барои замини худ қабул карда тавонед. Истифодаи ин технология иловаи донишҳои фаннӣ дорад; зеро ягон хато дар насб кардан ё танзими фишор метавонад ба фурӯниши болоб ё камшавии андозаи маҳсули ниҳоӣ оварда расонад.</p>\n\n<h2>Параметрҳои фаннии интихоби қаторбандӣ барои шибиҳо</h2>\n<p>Интихоби намуди қаторбандии мувофиқ, қадами аввал дар нигоҳдори дурусти шибиҳо аст. Шибиҳо, барҳамбарии томати ё хураки, ки шағуллаҳои тӯло доранд, маҳсулоти меҳнатӣ бо масофаҳои корзи метаксӣ мебошанд. Бинобар ин, масофаи байни қаторҳои корзи (Row Spacing) дар корзи шибиҳо одатан байни 25 то 30 сантиметр тағйир меёбад. Ин масъала боиси интихоби қаторбандӣ бо диаметри ва масофаи гулҳо мувофиқ мешавад, ки хеле муҳим аст.</p>\n<ul>\n<li><strong>Диаметри қаторбандӣ:</strong> Барои пиёз одатан аз лентҳои 16 ё 19 миллиметрӣ истифода мебаранд. Лентҳои ғафстор бар моеъҳои часпон мувофиқтар мебошанд, аммо барои пиёз, ки ба насби ором ниёз дорад, лентҳои стандартии кофӣ аст.</li>\n<li><strong>Фاصолаи сӯрохҳо (Emitter Spacing):</strong> Одатан 20 ё 30 сантиметр ба назар гирифта мешавад. Ин фосила бояд бо фосилаи шаклҳои ҳаппиш мувофиқат кунад, то ки об бевосита дар маркази шакл ҷойгир шавад.</li>\n<li><strong>Сохтори лента:</strong> Лентҳои каналдор (Channeled) барои хокҳои рудоракӣ (шуморӣ) ва лентҳои полимерии ҳамвор (Laminar) барои хокҳои донча (ризданакӣ) тавсия дода мешаванд. Бо назардошти таркиби хоки боғҳои пиёз, ки одатан шумур-ломи (шумурӣ-ломосӣ) аст, лентҳои каналдор аз гирифти сӯрохҳо беҳтар пешгирӣ мекунанд.</li>\n</ul>\n<p>Бояд диққат диҳед, ки ленты типӣ баъди охир шудани даври ғунҷиши пиёз бояд аз боғ берун карда шуда нигоҳ дошта шавад. Ин нуқта дар қисмҳои оянда дар бораи нигоҳдории таҷҳизот муфассалтар муҳокам мешавад. Аммо барои фаҳмиши беҳтари чӣ гуна таъсири системаи обӣ дигар маҳсулоти сабзавотӣ, ки решаҳои рӯи хокӣ доранд, таҳқиқи мақолаи <a href="https://navar-abyari.ir/comprehensive-guide-cucumber-drip-irrigation-tajik/">Рӯйхати мукаммали обёрӣ қатра-ҳокуи хурма</a> метавонад монандҳои фаннӣ-ро равшантар созад, зеро хурма ва пиёз ҳарду ба намуди баробар ниёз доранд.</p>\n<h2>Барномакунии овароиш ва идоракунии намуди хокӣ</h2>\n<p>Пиёз дар марҳилаҳои гуногуни афзоиш ба оби миқдорҳои гуногун ниёз дорад. Дармондори дурусти пиёз бо лентаҳои таминии оби дампосту ҳифз ниёз ба шинохти ин марҳилаҳоро дорад:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-پیاز-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری پیاز با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>коркард ва ҳифзи лентаи овароии барои пиёз</figcaption></figure>\n<ol>\n<li><strong>Марҳилаи тарунак (таъмини ибтидоӣ):</strong> Дар 2-3 ҳафтҳои аввал пас аз партофтани тохт, равғани ҷавон аст ва решаҳо заиф мебошанд. Овароиш бояд бо ҳаҷми кам ва даъвати зиёд (ҳар 1 то 2 рӯз) сурат гирад. Зидди фишори лента дар ин марҳила бояд ба ҳадди ақал расад, то ҳаракати тохт ё равғани бозгиштор нашавад.</li>\n<li><strong>Марҳилаи афзоиши вегетативӣ (афзоиши буттаҳо):</strong> Бо афзоиши сатҳи баргҳо, ниёз ба об зиёд мешавад. Дар ин марҳила, намуди хок бояд дар сатҳи 60 то 70 фоизи ҳадди ситони замин бошад. Истифодаи лента дар ин давра имконияти додани ҳамзамони об ва моддаҳои ғизоӣ (Fertigation)-ро фароҳам меорад, ки барои ғизои пиёз зарур аст.</li>\n<li><strong>Марҳилаи пучидани пиёз (шикарди пиёз):</strong> Ин марҳила ҳиссиётарин қисм аз ҷиҳати сифат аст. Кам шудани афтобии об метавонад боиси хурд шудани андозаи пиёз гардад. Аксари ин, намӣи беш аз ҳад овардиб ба афзоиши баргҳо ва хурд мондани бӯллбовона овардан мекунад. Тавсия дода мешавад, ки дар ду ҳафти охир пеш аз ҷамъоварӣ, шиддати обдиҳӣ то 50 фоиз кам карда шавад, то ки пӯсти пиёз сахт шавад ва муддати нигоҳдорӣ пас аз ҷамъоварӣ зиёд гардад.</li>\n</ol>\n<p>Идоракунии фишор дар паси нақоричаи нӯрип низ муҳимияти махсус дорад. Пиёз аз сабаби решаҳои нозук, ба обдиҳии шадид тоб намеоварад. Бинобар ин, фишори амалӣ набояд зиёдтар аз 1 то 1.5 бар бошад. Истифодаи регуляторҳои фишори мувофиқ дар асосҳои хатҳои шахакашунанда кафолати тақсимоти якхелаи об дар тамоми дарози нақоричаро таъмин мекунад.</p>\n<h2>Оптимизатсияи хок ва пешгирӣ аз сироят</h2>\n<p>Яке аз бартарии асосии нақоричаи нӯрип, имконияти хушк нигоҳ доштани сатҳи хок байни хатҳо мебошад. Ин хосият нигоҳдории пиёзро бо нақоричаи нӯрип аз ҷиҳати кам кардани бемориҳои зангарию қурчӣ осон менамояд. Қурҷҳое ба монанди <em>Botrytis</em> ва <em>Sclerotium</em> ки сабаби пӯсиши пиёз мебошанд, дар муҳити намнок ва ҳавоии зиёд бо суръати баланд афзоиш меёбанд. Бо обдиҳии қатрагонӣ, танҳо минтақаи решаӣ бартан мегардад ва сатҳи хок хушк боқӣ мемонад.</p>\n<p>Аммо, ин ҳолат метавонад барои баъзе зараррасҳо имконият фармош кунад. Баъзе зараррасони хокшинӣ барои пайгирии намӣ ба сӯи нақоричаи нӯрип ҳаракат мекунанд. Барои муқобила бо ин мушкилӣ, тавсия дода мешавад, ки аз шлаки пластикӣ ё пӯшиши пластикӣ сабук барои хатҳои пиёз истифода шавад. Ғайр аз ин, тайёр кардани хок бо илова кардани компост ё вермиккулит метавонад зеҳкшии хокро беҳтар кунад. Дар сурати он ки дар деҳаҳои ҳамсоя кӯмаки парҳезӣ мисли чӯпони чечук ҷамъ шудааст, идоракунии парҳезҳои ғизоӣ низ муҳимият меёбад. Барои оғох шудан дар бораи шароити кӯмаки парҳезҳои дигари ғизоӣ, ки метавонанд дар нақбандии парҳезии шумо ҷой гиранд, метавонед ба мақолаи <a href="https://navar-abyari.ir/mung-bean-seed-rate-per-hectare-afghanistan/">Миқдори тухми чечук дар гектар</a> Баҳоред, то ки мутмаин шавед, ки зичии муносиб дар боғҳои умумӣ таъмин мешавад.</p>\n<h3>Идоракунии гузоштани ҳашаракҳо тавассути навори тейп</h3>\n<p>Гузоштани ҳашаракҳо ба таври фаврӣ ва мустақим ба реша яке аз беҳтарин усулҳо дар системаи қатқаткунанда аст. Сабзи чормағз ба нитроген, калий ва иода ҳассос аст. Дар системаи навори тейп шумо метавонед ҳашаракҳоро, ки дар об ҳал мешаванд, бо дозаҳои кам ва такроршаванда одам созед. Ин амал боиси кам шудани намакнокӣ дар атрофи реша нисбат ба обёрӣ кардан бо оби боло мебошад. Нуқтаи асосӣ дар нигоҳдории сабзи чормағз бо навори тейп пешгирии ҷамъ шудани намакҳо дар фاصلҳои миёна аст; бинобар ин, пас аз ҳар давраи гузоштани ҳашаракҳо, як сикли обёрӣ кардан барои шустан (Flush) фаромӯш накунед.</p>\n\n<h2>Ҳашарот ва бемориҳои маъмулӣ ва роҳҳои муқобилат</h2>\n<p>Ҳар системои обёрӣ экосистемаи худро меорад. Дар бораи навори тейп, таҳдиди асосӣ <strong>Мӯҳ шудани сӯрохҳо (Clogging)</strong> аст. Мӯҳ шудан метавонад физикӣ (зарраҳои хурд) ё биологӣ (гулҳо ва бактерияҳо) бошад. Барои пешгирии ин мушкилӣ, системои тоза кардани об (фильтри сет ё диск) бояд ҳар моҳ шуста шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-پیاز-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری پیاز با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption>crop drip tape maintenance care сабзи чормағз</figcaption></figure>\n<p>Бемориҳои қараблудии хокзист дар пиёз, ба монанди склеротиния (Sclerotinia), агар зериризиши мувофиқ вуҷуд надошта бошад, маъмултар мегарданд. Гарчанде ки обёрӣ тавассути тампиро (барфшонакӣ) кӯмак мекунад, аммо дар хокҳои вазнин ё зич бояд аз зериризиши амудӣ (дренаж) низ истифода бард. Инчунин, баъзе зараранхоҳон, ба монанди трипс (Thrips), ки барои пиёз хеле зараррасонанд, дар шароити мушаххаси муҳитӣ рушд меёбанд. Гарчанде ки идоракунии онҳо тавассути моддаҳои кимиёвӣ аст, аммо кам кардани стресси решаҳо тавассути обёрии мунтазам, ихтисорнокӣи бокӣро дар муқобилати сироятҳо меафзонад. Барои дарки беҳтари даири зараранхоҳон дар системаҳои нав, тадқиқи манбае чун <a href="https://navar-abyari.ir/harisnoqi-i-juvi-shashparra-dar-yak-hektor/">раҳнамои муқобила ба сазоки хокӣ ва зараранхоҳони шашпола</a> метавонад фоидадор бошад, зеро баъзе зараранхоҳони хокӣ байни ин ду система муштараканд.</p>\n<h2>Нуқтаҳои амалӣ оид ба нигоҳубinii физикии ларичаи тампиро</h2>\n<p>Ларичаи тампиро одатан як маротиба истифода мешавад, аммо дар системаҳои бисёрсола нигоҳубinii ларича, нест кардан, пӯшидан ва кушодан барои фаслҳои оянда иҷро мешавад. Пиёз маҳсуле аст, ки барои он одатан ларичаҳои истеъмолшаванда истифода мешаванд, зеро ларича дар дохили хок дарад ишудааст ва пас аз ҷамъоварии пиёз, ларича берун оварда шуда, ҷамъ карда мешавад. Агар шумо хоҳед аз ҳамон ларича барои парвариши оянда истифода баред, бояд марҳилаҳои зеринро риоя кунед:</p>\n<ul>\n<li><strong>Шустани об (Flush):</strong> Пеш аз пӯшидан сарчашмаҳо, об бо фишори мувофиқ ва ҳарорати муносиб дар ларича гузаронида шавад, то чангҳо ва афкандиҳои дохилӣ шуста шаванд.</li>\n<li><strong>Полоиш: </strong>Назор бояд дар маҳлули таноби вайнер ё кислота (вобаста ба намуди ғуфур) тоҷшуда ва шуста шавад.</li>\n<li><strong>Хушк кардан: </strong>Назор бояд дар соя хушк шавад. Дар рӯшноии мустақими офтоб будан, полимери назорро вайрон мекунад.</li>\n<li><strong>Паккуни ва бастан: </strong>Назорҳо бояд ба шакли пурраи ролҳо бо фишори кам пилд шаванд, то ба даразҳои сӯрох фишор наояд ва сӯроҳҳо пӯшида нашаванд.</li>\n</ul>\n<p>Ба хотир доред, ки пиёз меҳвори тезафзун аст. Агар назорҳои типи шумо доимии чандсола дошта бошад, ҳатман онро пеш аз ин қабул кунед. Нақабул шудан ва хокпӯшии назор аз омили асосии камшавии самаранокии солҳои оянда аст. Ин нуқта дар нигоҳубinii пиёз бо назорҳои типи хеле муҳим аст.</p>\n<h2>Баррасии муқоисавӣ бо обёрӣ зери заминӣ</h2>\n<p>Баъзе кишоварон барои коҳиши бухоршавӣ, усули обёрии зери заминӣ истифода мебаранд. Оё ин усул барои пиёз беҳтар аст? Обёрии зери заминӣ обро бевосита дар қабати реша мерасонад ва бухоршавиро ба наздикӣ ба сифр мерасонад. Аз ҷониби дигар, пиёз меҳвори булибӣ аст, ки дар сатҳи хок ҷойгир мешавад. Расидани об тавассути лӯлаи зери заминӣ метавонад боиси тағйири намии хок дар атрофи булиб шуда, куфниши булибро ҳангоми қабул шадидтар кунад. Аз тарафи дигар, назорҳои типи сатҳӣ ба шумо назорати бешар дар сатҳи булиб медиҳад. Барои муқоисаи дақиқтар, метавонед мақола <a href="https://navar-abyari.ir/%d8%a2%d8%a8%db%8c%d8%a7%d8%b1%db%8c-%d8%b2%db%8c%d8%b1-%d8%b3%d8%b7%d8%ad%db%8c-%da%af%db%8c%d8%a7%d9%87%d8%a7%d9%86/">Ориёни зери заминаи растаниҳо</a> ҳаракат кунед, то фаҳмед, ки чаро ин усул ододан бар маҳсулотҳои булбӣ одатан ба андозаи намунаи тап нест.</p>\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё намунаи тап боиси пӯлидани пиёз мегардад?</h3>\n<p>Не, агар намӣи хок қатъиян беш аз 90% имкониятҳои деҳқонона нафаряд. Тағйирёбии намӣ, ки аз ориёни таматиллашуда ва зиёд такроршаванда сарчашма мегирад, дар асл ба пешгирии пӯлидани қоризӣ мусоидат мекунад. Пӯлидан вақте ҳосил мешавад, ки ориёни ғарқобӣ ва дарозмуддат бар булб таъсир мерасонад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-پیاز-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری پیاز با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>crop drip tape maintenance care پیاز</figcaption></figure>\n<h3>Беҳтарин замони камбудани пиёз дар системаи таматиллашуда кадост?</h3>\n<p>Замони камбудан ба шароитҳои маҳаллӣ вобаста аст, аммо одатан вақте, ки 70 то 80 фоизи баргҳо зард ва хобид (дар даст) бошад. Дар системаи таматиллашуда, бояд 10 то 15 рӯз пеш аз камбудан, ориёнро боздорад ё хеле кам кунад, то пусти пиёз хушк ва муқовиматманд шавад.</p>\n<h3>Фосилаи тасмои капилярӣ аз бӯли пиёз то чӣ қадар бояд бошад?</h3>\n<p>Одатан тасмои капилярӣ дар фосилаи 10 то 15 сантиметр аз маркази чароҳ (ду то се сантиметр ба сӯи дохили чароҳи намондан) ҷойгир мешавад. Ин фосила метавонад вобаста ба намуди хок тағйир кунад. Дар хоки зарракашиш, тасморо наздиктар ба бӯл ва дар хоки шабулӣ каме дуртар ҷойгир кунед, тонам рутубат дар минтақаи решаҳо марказӣ бошад.</p>\n\n<h2>Хулоса ва тавсияҳои охирин</h2>\n<p>Истифодаи тасмои капилярӣ дар парвариши пиёз як сармоягузории дарозмуддат барои зиёд шудани сифат ва кам шудани ҳадафҳои амалӣ аст. Нигоҳубини пиёз бо тасмои капилярӣ ниёз ба эҳтироми се қисм дорад: аввал танзими дуруси фишор ва суръати ҷараён, дуюм идоракунии дақиқи нӯрон ва рутубат ва сеюм нигоҳубини физикии тасмоҳо пас аз фурӯш. Бо риояи ин асосҳо, шумо метавонед ҳатто дар шароити камобӣ ба намуди инкишофи баробар ё баландтар аз обёрӣ расоед.</p>\n<p>Барои кӯлаконҳое, ки мақсади расонашдани кӯштҳои худро доранд, ба назар гирифтани давраи кӯштҳои стратегӣ низ муҳим аст. Пиёз метавонад дар давраи яксола бо бисёр меҳварҳои дигар истифода шавад. Дониши ҳадафҳои гиҳоҳои дигар дар кӯштҳои шумо ба таҳияи нақшагирии беҳтар мусоидат мекунад. Масалан, агар кӯштҳои шумо шомил аз парвариши дигар гулҳои хокаи дигар бошад, наздиккуни ба мақолаи миқдори фурӯшдани луби дар гектар метавонад ба шумо кӯмак кунад, ки чӣ тавр метавонед намуди инкишофи меҳвари дигари давраи кӯштҳоро бо ҳамон системаи обёрӣ беҳтар кунед. Саҳмеҳвар дар кӯлакории муосир, омехтаи илм бо таҷриба ва истифодаи хирадатар аз технология аст.</p>','Нигоҳубинон барои моҳи: Ҷузъияти муҳим ва принсипи обёрӣ бо қатра','Поя — яке аз маҳсулоти муҳими қазъии мебошад, ки ҳассосияти баланд ба намнокӣ ва шароити муҳити дорад. Истифодаи навори чучук (типи чучукӣ) метавонад ҳалли самаранок барои идоракунии мутоноки об ва зиёд кардани ҳосилнокӣ бошад. Дар ин мақола ҷумӯриҳои асосии парҳезнокӣ аз поя бо навори чучукро баррасӣ мекунем.','publish','closed','closed','nihohubini-moyi-nuqtai-obori',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
