INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Кабачок яке аз маъмултарин сабзавотҳои баргӣ мебошад, ки дар бисёр боғзорҳои Эрон ҷорӣ мешавад. Ин наботот бар сабаби равонию худравии асос ва суръати афзоиши баланд, ба бемориҳои гуногуни зараррасон оммавӣ аст. яке аз интихоботони асосӣ дар парвариши кабачок фароҳам расиши шароити муносиб барои афзоиши омили бемории мебошад. Обирӣи қутрӣ Ҳимояд ҷузъи асосӣ дорад Ҳимоя Ҳимоя Ҳимоя Ҳимоя Ҳимоя. Ин усул бо расидани об ва моддаҳои ғизоӣ мустақиман ба реша, намии сатҳии хӯрокро идора мекунад ва аз тобиши зиёди ҷисмҳои бехӯрокӣ ё ғурадонҳо пешгирӣ мекунад.</p><h2>Таъсири обирӣи қутрӣ ба идоракунии намӣ ва саломатии набототи кабачок</h2><p>Намии баланд яке аз омили асосии афзоиши сабзавотҳои заминию бемориҳои бактериявӣ дар боғзорҳои кабачок аст. Вақте ки аз обирӣи оммавӣ ё боронӣ истифода мебаранд, намии муҳити атрофи наботот зиёд мешавад ва ҷои муносиб барои фаъолияти спораҳо фароҳам меорад. Ба муқобили ин, системҳои <strong>обирӣи қутрӣ</strong> бо тақсимоти мунтазам ва идорашудаи об, аз хушкӣ будани нисбӣи сатҳи хӯрок дар рӯи бӯсти нигоҳдории наботот таъмин мекунанд. Ин ба сабаб мешавад, ки устувории ҳуҷайраҳо дар деворҳои наботот нигоҳ дошта шуда ва муқовимати наботот ба дохил шудани патогенҳо зиёд мешавад. Инчунин, пешгирӣ аз тобиши баргҳо, монеи фароҳам расидани шароити бумошиёни оммавӣ барои чаргонҳои обрасон ва интиқоди бемориҳои вирусӣ мешавад.</p><h2>Мубориза бо зараррасони ҳашарӣ: Коҷиҳо ва пашшаки сафед</h2><p>Зарароварони ҳашарӣ, махсусан кӯзанҳои афидҳо (Aphids) ва моҳҳои сафед (Whiteflies), аз душманони асосии боғҳои салат мебошанд. Ин ҳашарот тавассути хӯрдани шароби растани на танҳо боиси кивушавӣ ва тағйироти шакли баргҳо мегарданд, балки ҳамчун мизбони миёна барои интиқоли вирусҳо низ фаъол мешаванд. Арвёби наздики тирип тавассути идоракунии микроклимати боғ метавонад дар коҳиши шумораи ин зарароварон самаранок бошад. Рӯянии баланди баргҳо омили ҷозибатанӣ барои баъзе аз ин ҳашарот аст; бинобар ин, бо нигоҳ доштани хушкшавии нисбии фазои ҳавоӣ ва тар будани танҳо қисми решаҳо, метавон шароитро барои ҳаёти ин зарароварон нопарвозтар кард. Илова бар ин, истифодаи наздикҳои тирип шаффоф имконияти назорати бӯрии решаҳо ва шинохти зудҳисобии вайроншавии решаҳо тавассути заннаҳо ё кӯзҳои хокӣро фароҳам меорад. Дар ин самт, омӯзиши нуқтаҳои муҳим пеш аз насби наздикҳои тирип дар боғ метавонад ба деҳқонҳо кӯмак кунад, то бо насби дурусти лӯлаҳо, аз пӯшиш ва ба вуҷуд овардани нуқтаҳои тар ноинтизор пешгирӣ кунанд, ки ин нуқтаҳо метавонанд паноҳгоҳ барои ҳашарот бошанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کاهو-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های کاهو با آبیاری قطره‌ای - تصویر 1"/><figcaption>зарароварони ғаламӣ бемориҳои арвобӣ салат</figcaption></figure><ul><li><strong>Назорати мунтазам:</strong> Бо истифода аз ҳарифҳои зард барои назорати моҳҳои сафед ва таҳқиқи дақиқи баргҳо барои кӯзанҳои афидҳо.</li><li><strong>Идоракунии биологӣ:</strong> Арвобии наққаӣ бо коҳиши ниёз ба маъюбсозии сатҳӣ, ба зинда мондани душманони табиӣ, ба монанди асписте ва серхес, кӯмак мекунад.</li><li><strong>Идоракунии наздикҳо:</strong> Пакизиши мунтазами наздикҳои тирип барои пешгирӣ аз рушди бактерияҳо дар дохили лӯла, ки метавонанд ба реша таъсир расонанд.</li></ul><h2>Пешгирии бемориҳои қумарӣ: пӯсидагии реша ва хокистар</h2><p>Бемориҳои қумарӣ, махсусан пӯсидагии реша ва бستر (Pythium spp. ва Fusarium spp.) ва бемории спори сиёҳ (Downy Mildew), дар шартҳои хунук ва тар шадидтаранд. Обёрӣи қатрагӣ аз сабаби намедодани тамоми ҳаҷми хок бо об, боиси он мегардад, ки решаҳо дар минтақаи ғизо ва тарии оптималӣ боқӣ монанд, вале аз ҷамъшавии об дар чуқуриҳои ғайроғивор пешгирӣ менамояд. Ин раванд ба беҳтаршавии аэратсияи решаҳо (Root Aeration) кӯмак мекунад. Таъминоти коффи оксиген ба решаҳо механизми дифоии растаро мустаҳкам мекунед ва аз заифшавии системаи иммунӣ-и он барои муқобилат бо ҳуҷуми қумарҳо пешгирӣ мекунад. Дар бораи бемории моҳи хокистарӣ (Botrytis cinerea), ки асосан дар шартҳои тарии баланди баргҳо рух медиҳад, хориҷ кардани тарӣ аз сатҳи баргҳо пас аз обёрӣ (бо истифодаи қатраҳои дақиқ зери баргҳо) як чораи самараноки пешгирикунанда аст. Инчунин, назорати pH-и хок бо истифода аз маҳлулҳои ғизоӣ тавассути системаи қатрагӣ, метавонад аз рӯйиш баъзе қумарҳои хокӣ, ки дар хокҳои турш беҳтар рӯй меоваранд, пешгирӣ кунад.</p><h2>Нақши таъмини мувозунат ва идоракунии EC дар кам кардани стресс ва беморӣ</h2><p>Яке аз манфиатҳои пинҳонии системҳои нӯри натиб, имконияти фитотеризатсия (Fertigation) ё зеркундан маводи ғизоӣ ва ҳатто баъзе маводи мулоимгаро ба системаи обёрӣ мебошад. Бо танзими дақиқи консентратсияи намекҳо (EC) ва pH-и маҳлули ғизоӣ, метавон стресси камبودии элемент дар растаро кам кард. Растае, ки аз ҷиҳати ғизо солим аст, девораҳои селулиёии қавитар дорад ва камтар барои зиким барҷаи ҳашаротҳо ё вориди патогенҳо эҳтиёткорӣ мебошад. Барои деҳқонон, дарк кардани робита байни ғизо ва муқовимати раста муҳим аст. Шумо метавонед барои шиносоӣ бо принсипҳои идоракунии нӯри натиб, ба роҳнамои <a href="https://navar-abyari.ir/payvasthoi-navori-tip-kishovarzi/">Девомии нӯри натиби кишоварзӣ</a> Муталлаот бароеманд, ки нуқтаҳои муҳимро дар бораи нигоҳдории асбобҳо иероран мекунад. Инчунин, истифодаи обдиҳии дақиқ метавонад аз шӯршакӣ ва ба вуҷуд омадани гурӯҳҳои нофизики намак дар сатҳи хок пешгирӣ кунад; шӯршакӣ метавонад решаҳоро зарар расонад ва бутаро заиф ва ба беморӣ дучор созад.</p><table><thead><tr><th>Омили беморӣ/заҳмонӣ</th><th>Шароити паҳншавӣ</th><th>Ҳалли масъала бо обдиҳии қатрагӣ</th></tr></thead><tbody><tr><td>Фасидани реша (Pythium)</td><td>Обгирии хок, ҳарорати баланди хок</td><td>Кам кардани ҳаҷми обдиҳӣ, зиёд кардани шумораи таваҷҷӯҳ, обдиҳии мувофиқ</td></tr><tr><td>Кӯбӣҳои хокистарӣ</td><td>Рӯғъати баланди баргҳо, ҳавокашии номувофиқ</td><td>Баромади қатрагӣ зерин барг, ҳавокашии хонаи парранда, гармкунии назоратшуда</td></tr><tr><td>Ҷусеҳои хурд</td><td>Рӯғъати баланд, андозагирии тези растанӣ</td><td>Назорати микроклимат, назорати давомӣ, камшавии рӯғъати nisбии сатҳ</td></tr><tr><td>Пасеропа (Xanthomonas)</td><td>Заъфи физикӣ, баромади зарраҳои хурд, рӯғъати баланд</td><td>Паҳлӯгири дар назорати барг, таъкиди растанӣ бо хӯрокпарории дуруст</td></tr></tbody></table><h2>Нуқтаҳои амалӣ барои соҳиборӣ ва гӯгарамҳо</h2><p>Иҷрои дурусти системаи ороиши қатрагӣ дар кабудӣ ниёзманди диққат ба ҷузъиёт мебошад. Фосилаи носелҳо ва ҳаҷми дараомиш бояд бар асоси андозаҳои анор чархдифл кунанда ошкор шаванд. Дар соҳиборӣ, интихоби боби тиби бо сӯрохҳои мувофиқ барои пешгирӣ кардани баромадани об ба самти шилоби бемарҳо муҳим аст. Дар гӯгарамҳо, идоракунии шилоби нисбӣ ва истифодаи системаҳои бадбад (Fan) дар паҳлу бо ороиши қатрагӣ, калиди муваффақият аст. Инчунин, истифодаи филтрҳои мувофиқ дар системаи ороиш ворид шудани зарраҳо ба носелҳоро пешгирӣ мекунад; зарраҳоеро, ки метавонанд муҳитро барои афзоиши бактерияҳо эҷод кунанд. Соҳибзороне, ки дар ҷустуҷӯи бехтарсозии маҳсулоти монанд ба zichиши кадам иштиҳо доранд, метавонанд аз таҷриботи мавҷуда истифода бароранд; масалан, таҳқиқ кардани <a href="https://navar-abyari.ir/harvest-yield-black-radish-hectare-factors/">Омилҳои самаранок ба ҳаҷми ҳосили чигари сиёҳ дар гектар</a> метавонад назари беҳтарро дар бораи идоракунии решаҳои ҳассос ба шилобӣ пеш бинад, гарчанде кабудӣ анори баргдор аст, аммо принсипҳои идоракунии шилоби решаҳои умумӣ мебошад. Барои маҳсулоти дигари баргдор низ метавон аз намунаҳои монанд истифода барорид, мисли дастурам <a href="https://navar-abyari.ir/%D8%B1%D8%A7%D9%87%D9%86%D9%85%D8%A7%DB%8C-%D8%AC%D8%A7%D9%85%D8%B9-%DA%A9%D8%A7%D8%B4%D8%AA-%DA%A9%D8%AF%D9%88-%D8%AA%D8%AE%D9%85%DB%8C/">Раҳнамои ҷамъи кадам кардани хурмо</a> ки нуқтаҳое оид ба фосилаи кадам ва ниёзҳои решаҳоро зикр мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کاهو-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های کاهو با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation кӯбудӣ</figcaption></figure><h2>Саволҳои маъмулашуда (FAQ)</h2><h3>Оё оғозкунии чуқорӣ (капиллярӣ) ҳатм ба ғайб бардоштани зарарзанандаҳои ҳашаротӣ имкон медиҳад?</h3><p>Не, оғозкунии чуқорӣ як асбоби пешгирикунанда аст, ки шароити рӯшании зарарзанандаҳоро номаъмул менамояд, вале ҷойгузини заҳролорӣ ё контроли биологӣ намешавад. Ин усул аз эҷоди муҳити таркӣ барои хурдунокӣ ва зиндагии баъзе ҳашарот пешгирӣ мекунад.</p><h3>Чӣ миқдори таркии хок барои салот дар системаи чуқорӣ мақбул аст?</h3><p>Вобаста ба марҳилаи рушд, одатан таркии решагӣ дар ҳудуди 50 то 65 фоизи сатурацияи мутлак идеалӣ аст. Монебачии таркӣ бо сенсорҳо тавсия дода мешавад, то аз оғозкунии зиёд, ки боиси гудунии решаҳо мегардад, пешгирӣ карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-کاهو-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های کاهو با آبیاری قطره‌ای - تصویر 3"/><figcaption>зарарзанандаҳои ҳашаротӣ бемориҳои сабззот оғозкунии чуқорӣ салот</figcaption></figure><h3>Оё ин система барои ҳосилоти решагони ҳассос низ истифода бурда мешавад?</h3><p>Бале, барои дигар ҳосилоти решаги ҳассос ҳам асосҳои монанд вуҷуд доранд. Шумо метавонед барои муқоисаи коэффисиентҳои оғозкунии дигар ҳосилотҳо ба дастраҳкунандаи <a href="https://navar-abyari.ir/cucumber-seed-per-hectare-guide/">Дар бораи тоҷи херча бар гектар</a> Барои маъмурӣ кардани намӣ дар ҳосилҳои ҳассос ба об, ба ин нуктаҳо диққат диҳед.</p><h2>Хулоса</h2><p>Маъмурӣ кардани зараранокҳо ва бемориҳои каду бо обкорӣ-андозаи қатраи, як омехтаи илм, дақиқӣ ва назорати доимӣ мебошад. Бо истифодаи дурусти системаҳои пистонии ва қатраи, на танҳо дар сарфи об ва энергия таҳсилот мешавад, балки имнигирии наботот ба муқобилати патогенҳо мустаҳкам мегардад. Мусоид аст, ки деҳқонони азиз ба муҳимоти насб ва нигоҳдории системаҳои обкории худ диққати махус дошта, аз манбаъҳои ихтисосӣ истифода барад, то хатарҳои биологии деҳро ба минимум расонанд.</p>','Идоракунии зарароварон ва бемориҳои каҳу бо истифодаи беҳтар аз обии чангҳо','Салат чун маҳсули ҳассос, ба идоракунии дақиқи оборӣ ниёз дорад. Дар ин мақола мо таҳлил мекунем, ки чӣ гуна обории қатрагӣ метавонад дар кам кардани намнокӣи баргҳо ва пешгирӣ аз бемориҳои қаламфушӣ кӯмак расонад.','publish','closed','closed','bemoirihoi-kahu-obi-i-changi',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
