INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','تعرف على كمية بذور زیرعقدار اللازمة لكل هكتار لتحقيق أقصى مردودية باستخدام التقنيات الحديثة للري بالتنقيط والري بالتنقيط، مع توجيهات عملية للمزارعين العراقيين.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
