INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Кишт <strong>Кишнӣш</strong> Чун яке аз маъмултарин растаниибобҳо ва обори, ба нақшагирии дақиқ дар ҳамаи марҳилаҳои истеҳсол ниёз дорад. Аммо ҳеҷ марҳилае ба ҳадди <strong>кишт</strong> ҳаётӣ нест; зеро агар миқдори бобиш кишиниш дар гектар дуруст ҳисоб накарда шавад, ҳамаи заҳматҳои обёрӣ ва идоракунии боғ беҳуда хоҳад буд. Бисёр деҳқонҳо ҳанӯз бо роҳҳои анъанавӣ амал мекунанд ва бобишро паҳн мекунанд, дар ҳоле ки бо шинохти дуруст андозаи кишт ва системаи обёрӣ, метавонанд маҳсулоти ду ҷӣнофтода ба даст оранд. Дар ин дастоварди муфассал, мо танҳо ба рақамҳо ишора намекунем, балки чӣ гуна танзими <strong>миқдори бобиш кишиниш дар гектар</strong> ро ба асоси шароити иқлимӣ, намуди хок ва усули обёрӣ (қафоз ва навори типӣ) шарҳ медиҳем, то боғи шумо беҳтарин самаранокӣ дошта бошад.</p><h2>Чаро ҳисобкунии дақиқ бобиш кишиниш дар гектар муҳим аст?</h2><p>Таркиби дуруسته, ки барои бӯд истифода мекунед, бевосита ба рақобати гиёҳҳо барои об ва ғизо таъсир мерасонад. Агар зичии бӯд хеле зиёд бошад, гиёҳҳо лағжак ва заиф мекашанд ва дар муқобили бемориҳои зӯбакӣ бартарӣ пайдо мекунанд. Аз ҷониби дигар, камбудии зичӣ боиси он мегардад, ки аз имкониятҳои истеҳсолии замин истифода нашуда, алафҳо фурсат гиранд, ки бартарӣ пайдо кунанд. Шабатги гиёҳест, ки суръати рӯяндагии ибтидоиёнаш тез аст, бинобар ин аз ҷиҳати иқтисодӣ, истифодаи бӯди иловагӣ ҳамоҳанг бо ҳарҷи иловагӣ ва эҷоди намнокнии нопок дар сатҳи хок мебошад. [link:миқдори бӯди муносиб дар гектар барои афзоиши ҳосил](https://navar-abyari.ir/miqdori-tukhmi-musir-dar-gektar-rohayi-afzoyishi-hosil/)</p><h2>Таъсири системаи оварии навар (лентӣ) ба интихоби андоза (метраж)</h2><p>Яке аз бузургтарин дастовардҳои муосир, имконияти идоракунии дақиқи намнокнии реша бо истифода аз <strong>навари абӣ</strong> мебошад. Дар системаҳои оварии қаптоии, фавқ баъдҳо бояд бо гилави ва даби баромади қаптокҳо мувофиқат кунад. Вақте ки аз навари абӣ истифода мебард, одатан масофаи байни сатрҳои бӯд (метражи дарозӣ) ва масофаи лӯлаҳо аз ҳам (метражи андоза) муайян карда мешавад. Шабатги одатан дар масофаи 5 то 15 см дар тӯли сатр бӯд мешавад. [link:type irrigation tape installation method](https://navar-abyari.ir/type-irrigation-tape-installation-method/)</p><p></p><p>Нуқтаи калидӣ дар ин ҷост, ки вақте аз навар истифода мебард, зичии гиёҳҳо дар зеринсобиҳои оварӣ бояд ба таври ишора бошад, ки решаҳо метавонанд ба решаҳои ҳамсол бирасанд, то аз бухоршавии об пешгирӣ кунад. Бинобар ин, ҳисобкунӣ <strong>миқдори бӯди шабатги дар гектар</strong> бояд асосан ин масофаҳои стандартӣ анҷом шавад. Ҳар қадар масофаи лӯлаҳои навар бештар бошад, метавон метражи дарозии бӯдро каме зиёд кард, то пӯшиши беҳтар эҷод шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گشنیز-در-هکتار-راهنمای-جامع-تصویر-شاخص.webp" alt="مقدار بذر گشنیز در هکتار: راهنمای جامع - تصویر 1"/><figcaption>меъёри ҷӯр дар ҳектар барои ҷанибӣ (гзеніз)</figcaption></figure><h2>Миқдори стандартии ҷӯри ҷанибӣ дар ҳектар</h2><p>Барои ҳисобкунии дақиқ, бояд бо се тағйирёбандаи асосӣ сарукор дошта бошем: дарозии қатор, масофаи байни қаторҳо ва вазне, ки дар ҳар метри мурабқарор нест. Ба таври умумӣ, миқдори ҷӯри ҷанибӣ дар ҳектар вобаста ба шароити иқлимӣ аз 15 то 25 килограмм тағйир меёбад. Аммо барои расидан ба сифати аъло, мо миқноси стандартиро пешниҳод мекунем:</p><table><caption>Ҷадвали роҳнамои ҳисоби ҷӯри ҷанибӣ</caption><tbody><tr><th>Масофаи байни қаторҳо (сантиметр)</th><th>Масофа дар тӯли қатор (сантиметр)</th><th>Шумораи растаниҳо дар ҳектар</th><th>Миқдори тақрибии ҷӯр (килограмм)</th></tr><tr><td>30</td><td>5</td><td>6 666</td><td>Тақрибан 15 то 17</td></tr><tr><td>25</td><td>4</td><td>10 000</td><td>Тақрибан 20 то 23</td></tr><tr><td>20</td><td>3</td><td>16,666</td><td>Тақрибан 25 то 28</td></tr></tbody></table><p>Диққат дошта бошед, ки ин рақамҳо ба оҳанги 300 грамм бода ба метри мукабаъ (бо фарзи масоҳати кофӣ кунӣ) асос доранд. Агар бода шумо нӯх (пирӯя) бошад, ҳатман меъёри онро камтар ба назар гиред, то инки часпидани решаҳо дар оғоз пешгири шуда шавад. [link:mikyori hosili marza dar yek gektar rahnamoi purra](https://navar-abyari.ir/mikyori-hosili-marza-dar-yek-gektar-rahnamoi-purra/)</p><h2></h2><p>Бодаи гунҷиҳо бар сабаби андозаи хеле хурд доим яке аз чалашҳои кунӣ мебошад. Бар сабаби хурдии дон, ҳангоми паҳн кардан, баъзан ҷамъшавии зиёд дар як нуқта ва холигӣ дар нуқтаи дигар рух медиҳад. Барои ҳалли ин мушкилот, метавон аз усулҳои кунӣ бо гиреҳбаст (Roller) истифода барад, ки барои гунҷиҳо хеле муваффақ аст.</p><h2>Нуқтаҳои амалӣ барои кунӣ кардани гунҷиҳо бо ришип (тиб)</h2><p>Дар системаи обёриӣ бо ришип (тиб), шумо аз чандирӣ дар кунӣ бархӯрд мекунед. Барои гирифтани беҳтарин натиҷа, лутфан ба ин нуқтаҳои амалӣ диққат диҳед:</p><ol><li><strong>Омодагирии хок: </strong> Пеш аз эҷоди рафти намдор хокро бо диски то чуқурии 30-40 сантиметр обӯр кунед, то ки решаҳои занҷабил бе муқобимат руиянд. Занҷабил ба хокшиканӣ ниёз дорад.</li><li><strong>Васеъкунии хатҳои намдор: </strong> Мутмаин шавед, ки масоҳати лӯлаи рафти намдор аз маркази сатри кадан тақрибан 15 то 20 сантиметр бошад, то ки решаҳо хуб дар ҳудуди намнок монанд.</li><li><strong>Идоракунии фишор: </strong> Фишори мувофиқ барои рафти намдор одатан 1 то 1.5 бар аст. Барои занҷабил, ки решаҳои ҳассос дорад, фишори камтар (100-120) маъқултар аст, то аз хуфгии ғилом пешгирӣ шавад.</li><li><strong>Омодагии зери абӣ: </strong> Азбаски масоҳат байни сатрҳо барои занҷабил кам аст, истифодаи малинг (чипинг) бисёр хуб аст.</li></ol><p></p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گشنیز-در-هکتار-راهنمای-جامع-کاربرد-عملی.webp" alt="مقدار بذر گشنیز در هکتار: راهنمای جامع - تصویر 2"/><figcaption>нормаи ҳосилбарии бехар барои ҷуҷуб (gishniz)</figcaption></figure><h2>Ниқотҳои техникии маҳаллӣ ва моҳвоӣ</h2><p>Агар шумо дар минтақае бо намӣи баланд ҷойгир бошед, зичии бехоро коҳиш диҳед, то аз вайроншавии қарақум (қарачи) камтар гардад. Дар минтақаҳои хушк намӣ пасттар аст, аммо ҷуҷуб ба обории музоҳимантар ниёз дорад. [link:al ray bil akhadid](https://navar-abyari.ir/al-ray-bil-akhadid/) усули кӯҳонтари обдорӣ аст, ки нисбат ба навар чопӣ сарфи оби зиёдтар дорад ва барои ҷуҷуб чун як маҳсулоти ҳассос ба намӣ, усули навар чопӣ муайянтар аст. Истифодаи навар чопӣ ба шумо кӯмак мекунад, ки ҳатто дар ҳавои гарм намии решаҳоро собит нигоҳ доред, ки ин боиси зиёдшавии истеҳсоли равғони эфирӣ дар ҷуҷуб мегардад.</p><h2>Саволҳои маъмул дар бораи миқдори беҳи ҷуҷуб дар гектар</h2><h3>1. Оё миқдори беҳи ҷуҷуб дар гектар барои коркиши зимистонӣ бо коркиши тобистонӣ фарқ мекунад?</h3><p>Ҳа, ҳастанд. Дар коркиши тобистонӣ, ки ҳарорат баландтар аст, метавонед зичии бехоро каме зиёдтар аз сатҳи миёна дида бароед, то ки рӯяниҳо аз стресси ҳароратӣ ва хушкӣ камтар ронгид кунанд. Дар коркиши зимистонӣ, агар минтақаи шумо сард бошад, одатан зичии пасттарро интихоб мекунем.</p><h3>2. Оё беҳи ҷуҷубро мумкин аст бевосита дар болои навар чопӣ ҷойгузорӣ шавад?</h3><p>Не, ҳаргиз беҳро бевосита болои навар чопӣ партошед. Шумо бояд беҳро дар масофаи муайян аз лаблабкунанда (пайдарпай) насб кунед. Вазифаи навар чопӣ ин расонидани об ба реша аст, на ҷойгузории беҳ. Ин боиси ин миқдор мешавад, ки баъзан бехони дар ҳолати афзоиш бо лӯлаҳо тамос мегиранд, ки ин боиси захмӣ шудани пои бех метавонад гардад.</p><h3>3. Беҳтарин замон барои ҳисобу Kitоб дости будони бӯронро кист?</h3><p>Бояд пеш аз ҳама, бӯронро аз ҷиҳати нӯбудии (қуввати) озмӯшӣ донед. Агар нӯбудӣ аз 90% камтар бошад, миқдори бӯронро зиёд кунед, то шумораи мақсаднок ҳисоб карда шавад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/مقدار-بذر-گشنیز-در-هکتار-راهنمای-جامع-جزئیات-فنی.webp" alt="مقدار بذر گشنیز در هکتار: راهنمای جامع - تصویر 3"/><figcaption>seed rate per hectare crop гушниз</figcaption></figure><h3>4. Чӣ тавр нӯрбатибро барои парҳоври ғушниз иваз кардани?</h3><p>Барои ғушниз, фосила миёна дуюм нақши ғушниз ҷиҳат кӣшт барои қатӣ кам аст (тақрибан аз 20 то 30 сантметр). Нӯрбатибҳо бо қотҳои камтар (масалан, 16 миллиметр) ва миёна 20-25 сантиметр беҳтар аст. [link:Нӯрбатиб ҳифз ва хароҷот](https://navar-abyari.ir/%d9%86%da%af%d8%ad%d8%b1%d8%af%d8%a7%d8%b1%d9%8a-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%86%d9%88%d8%b1-%d9%88-%d9%87%d8%b2%d9%86%d9%87/)</p><h3>5. Оё нӯрбатиб ба рушди зидди иллати ғушниз мерасад?</h3><p>Бале, бо сабаби расидани ороқро ба реша дар ҳарорати мақсаднок, рушди ғушниз дар минтақаҳои нӯрбатиб одатан 10 то 15 рӯз бошидтар аз ороқ кардани дастӣ аст.</p><h2>Хулоса</h2><p>Интихоби миқдори дурусти тоҳукҳои кини ҳазор дар гектар як ҳунаст аст, ки якҷояшавии дониши кишоварзӣ ва обии муосирро дар бар мегирад. Бо истифода аз усулҳои нӯри чизи (типӣ) ва риояи зичии ғӯлом, шумо метавонед маҳсулот бо сифати аъло ва фоизи иқтисодии баландтарро пешниҳод кунед. ҳамеша дар назар дошта бошед, ки паҳншавии баробардаради тоҳук калиди муваффақият аст. Маслиҳати ниҳоии мо ин аст, ки барои ғӯломи оянда аз тоҳукҳои пӯстидашуда (пӯстдор) истифода баред ва бо нӯри чизи (типӣ) мувофиқ бо фишори паст оғози оро об кунед. Ин амал на танҳо истеъмоли обро беҳтар мекунад, балки сифати кини шуморо барои бозорҳои экспортӣ ҷаззоб менамояд.</p>\n<p><strong>Мавзӯҳои робитадошта:</strong> <a href="https://navar-abyari.ir/miqdori-tukhmi-musir-dar-gektar-rohayi-afzoyishi-hosil/">miqdori tukhmi musir dar gektar rohayi afzoyishi hosil</a>， <a href="https://navar-abyari.ir/hosilnokiya-chukandari-qand-dar-gektar-omilhoi-muassisir/">hosilnokiya chukandari qand dar gektar omilhoi muassisir</a>， <a href="https://navar-abyari.ir/type-irrigation-tape-installation-method/">type irrigation tape installation method</a>， <a href="https://navar-abyari.ir/%d9%86%da%af%d9%87%d8%af%d8%a7%d8%b1%db%8c-%d9%86%d9%88%d8%a7%d8%b1-%d8%aa%db%8c%d9%be-%d9%88-%d9%87%d8%b2%db%8c%d9%86%d9%87/">Нигоҳубини нӯри чизи (типӣ) ва хароҷот</a></p>','Миқдори боби бодиринг дар гектар: Роҳнамои мукаммал барои баланд бардоштани самаранокии дар обёрӣ бо усули қатра ва навбати тартиб','Дар ин мақолаи пурра шумо ҳамаи сирри ҳисобкунии дақиқи бобуки шафрон дар як ҳектарро меомӯзед. Аз интихоби зичии мувофиқ барои обёрӣи намоишӣ то нуқтаҳои асосии зиёд кардани истеҳсолот. Раҳнамои амалӣ барои коррони заминҳои касбӣ.','publish','closed','closed','miqdori-bodi-ring-dar-hektar-abori-qatra-tarib',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
