INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Дар ин мақола тафсилот дар бораи миқдори зарурии боби бодиринг дар як гектар барои дастёби самаранокии баланд дар ҳангоми истифодаи системаҳои обёрӣ ба монанди қатра ва навбати тартиб оварда шудааст. Роҳнамои мукаммал барои муҳофизи кишоварони Тоҷикистон.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
