INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Омӯзиш ва баррасии ҳаҷми ҳосили сорго дар ҳар ҳектар бо истифода аз усули қатории тӣбӣ. Маълумотҳои муфассал барои деҳқонон.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
