INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<h2>Муқаддима: Чаро кӯшокиш дар ороғкунии қатрагӣ таъсирпазиртар аст?</h2>\n<p>Кӯшокиш як наботи сабзӣхӯр бо эҳтиёҷи зиёд ба об, аммо толибнокӣи паст ба намии бад-и реша аст. Дар усулҳои анъанавии ороғкунии масли абшун, намии баланди таҳи хок муҳити муътомидро барои рушди вайроншавиши решаҳо ва гоммӯгҳо ташкил медиҳад. Аммо вақте ки <strong>ороғкунии қатрагӣ</strong> истифода мекунем, ҳадаф аз мо идоракунии дақиқтари намии минтақаи решаҳо аст, то ҳам эҳтиёҷи наботи иҷро шавад ва ҳам аз ташкили шартҳои мувофиқ барои фаъолияти зиёди зараррасонҳои хокӣ пешгирӣ намоем. Ин мақола ба таҳлили мушкилоти махсуси наботи кӯшокиш дар муносибат бо системаҳои нав ороғкунӣ мегарданад.</p>\n\n\n\n<h2>Таъсири нақши ороғкуни дар паҳши бемориҳои қарчҳо</h2>\n<p>Яке аз муҳимтарин нуқтаҳо дар парвариши кӯшокиш идоракунии намии нисбии таҳост. Агар ороғкунӣ бебова ва зиёда аз ҳад амалӣ шавад, нафаскашии решаҳо маҳдуд мешавад ва набот аз нигоҳи амният заиф мегардад. Ин заифӣ, дарвозае барои воридшавии патоженҳои масли <em>Pythium</em> ва <em>Fusarium</em> ки сабаби вайроншавии хокишакӣ ва реша мебошад.</p>\n<h3>Нақши тасмаи нибобарӣ дар кам кардани тамоси мустақим</h3>\n<ul>\n<li><strong>Нибобарии тасма (Tape Irrigation):</strong> Ин система бо сабаби ҷараёни якхелаи об, сабаб мешавад, ки тӯбдорӣ дар чуқури махсус ба шакли як тасмаи torik нигоҳ дошта шавад, на дар тамоми сатҳи хок.</li>\n<li>Бо кам шудани тӯбдорӣ дар сатҳи тиҷи кӯрӣ, эҳтимоли ба вуҷуд омадани бемориҳои баргҳо, ба монанди далдаҳои булӯрӣ, паст мешавад.</li>\n<li>Истифодаи қатрагирҳои мувофиқ бо масофаи мувофиқ аз гулӯи кӯрӣ, аз интиқоли об ва хок ва пешгирии паровии спораҳои зангзорӣ ба баргҳои нав нигоҳ медорад.</li>\n</ul>\n<p>Барои фаҳмиши беҳтари намунаи мувофиқи об, шумо метавонед ба роҳнамои <a href="https://navar-abyari.ir/how-to-determine-tape-irrigation-points/">Муайян кардани нуқтаҳои нибобарии тасма</a> ро муроҷиат кунед, то аз паҳншавии якхелаи тӯбдорӣ боварӣ ҳосил созед.</p>\n\n<h2>Арбогиҳо ва беморҳои физиологии ва кимиёвӣ дар системаи қатрагӣ</h2>\n<p>Собори қатрагӣ на танҳо як усули соборӣ, балки як воситаи идоракунии кимиёвӣ (фиториминг) аст. Бисёре аз беморҳо ҳассосият ба тағйирёбии зудшавандаи намии хок ва талпонии обро нишон медиҳанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-جعفری-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های جعفری با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation жасури</figcaption></figure>\n<h3>Шустани намии хок ва назорати моҳи (пудра) ва шипакҳо</h3>\n<ol>\n<li><strong>Зиёд кардани фишори шустисабз:</strong> Баъзе арбогиҳои хурд, ба монанди аклемидинҳо, дар зери фишори ҷараёни оби қатрагӣ шуста мешаванд ё муҳити эҳсоси онҳо тағйир меёбад.</li>\n<li><strong>Кам кардани суръати афроридани олдҳо:</strong> Агарчун ки жасур сарпакафрас нест, намои маҳдуди рӯшноӣ метавонад суръати афроридани олдҳои рақобаткорро дар тӯли партоб кам кунад.</li>\n</ol>\n<p>Дар ҷанби ороғидаштан, ғизои муносиб нақши муайянкунанда дорад дар баққати гиёҳ. Барои шиносӣ бо асосҳои ғизоӣи гиёҳҳои сабзӣ, мақолаи аҳамияти бодаи Сеизмин Ноаре Тип ва Лӯла (ки ба асосҳои асосии ғизо ва ғарф кардан мерӯяд)-ро омӯзед. Азбаски таъкид мекунем, ки интихоби бодаи солим қадами аввал дар пешгирии зараррасониҳои дохилӣ аст.</p>\n\n\n\n<h2>Чаллаҳои махсуси ҷаффарӣ: хӯрди гил ва реша</h2>\n<p>Ҷаффарӣ ҳассосияти баланде ба хӯрди гил (Crown Rot) дорад. Дар системаҳои ороғидаштан, ки дуруст нест, об атрофи гил маҷмӯъ мешавад. Агар партоби ноҳафчашонҳо аниқан зери гил бошад, боиси паштодани намӣ ва фаъолияти зангинони муҳаллағӣ (Rhizoctonia) мегардад.</p>\n<h3>Талаботҳои амалӣ барои пешгирии хӯрди гил</h3>\n<ul>\n<li><strong>Идоракунии баландии хурд (Custard):</strong> Дар вақти ғарф кардан, баландии хурд атрофи гил идода кунед, то об аз он берун шавад.</li>\n<li><strong>Таъмини баландии партоб:</strong> Партоби Тип-ро чунон бичеҳед, ки партоби об аз як тарафи гил (масалан, паси гил) анҷом шавад, на аз ҷое, ки намӣ бевосита ба бафтаи гил бозад.</li>\n<li><strong>Истифодаи пӯшишдиҳӣ (мулч):</strong> Пӯшишдиҳӣ бо пластики шаффоф ё нурии кӯҳӣ рушди намнокӣи заминро ҳисса нигоҳ медорад ва дар хуви замини тарро маънои ростгӯнаро пешгирӣ мекунад.</li>\n</ul>\n<p>Ҳамчунин, дар минтақаҳои гарм, ки зантобурро офати рӯшноии мутлақ меоҳанзад, истифодаи лентаи тақридан дар ҷои системаи қатраи ҷудосупазазӣ санҷиши беҳтари ҳарорати замини атрофи решаҳоро таъмин мекунад. Ҳамчун манбаи иловаии маълумот, шумо метавонед <a href="https://navar-abyari.ir/fawaid-nawwar-riyy-atip/">фоидҳои лентаи тақриданро</a> меоҳанзед, то бенамудан ошкории ин система дар шартҳои гуногуни табиӣро беҳтар фаҳмед.</p>\n\n<h2>Ҷадвали идоракунии зараррасонҳо дар системаи обёрӣи қатрадорӣ</h2>\n<p>Дар поён таъсиси тадбирҳои назорати зараррасонҳои зантобур дар вобастагӣ бо обёрӣ намоиш дода шудааст:</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-جعفری-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های جعفری با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation зантобур</figcaption></figure>\n<table border="1" cellpadding="5">\n<thead>\n<tr><th>Номи зараррасон/беморӣ</th><th>Сабаби шиддатёбӣ бо аррозии номувофиқ</th><th>Равиши ислоҳи орозии чуққура/шаҳоб</th></tr>\n</thead>\n<tbody>\n<tr><td>Коридаи реша (Pythium)</td><td>Бомоӣ (бӯғо) замин ва камшавии оксиген</td><td>Зиёд кардани импулси орозии ва кам кардани ҳаҷм; истифодаи шаҳоб бо порометрии баланд</td></tr>\n<tr><td>Дадҳои қаҳвахӯй (Septoria)</td><td>Баррагии баланди баргу шустан бо оби чуққура</td><td>Ҷудо кардани пилсани об аз роҳи баргҳои поёнӣ; истифодаи тампониҳо бо пилсандагӣ</td></tr>\n<tr><td>Гузарҳои рӯйи заминӣ</td><td>Камبودии оксиген ва зичии хок</td><td>Афзояди нфузаданӣ бо mulch пашшӣ ва коҳиш баъзе намӣ бо рӯйи нӯҳе</td></tr>\n</tbody>\n</table>\n\n\n\n<h2>Нуқтаҳои амалӣ барои кишоварии омехта</h2>\n<p>Баъзан хурсоқ бо дигар сабзбиёт дар кишоварии омехта кӯфта мешавад. Дар ин ҳолат, ҳамроҳии ороиш муҳим аст. Растаниҳо бо тафовути зарурати об набояд аз як системаи номуайяни истифода баранд. Масалан, агар хурсоқро бо растаниҳои зичтари рӯйи омехта кӯфтед, ба танзими дақиқи ҳаҷми об ниёз доред. Дар ин замина, дарки фарқияти зарурати об дар растаниҳои гуногун муҳим аст. Шумо метавонед бо хондани дастуравии <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%ac%d9%88-%d8%a8%d9%87%d8%a7%d8%b1%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Ҳаҷми ҳосили ҷӯи баҳорӣ дар гектар</a>намунаи идоракунии ҳаҷм ва обдиҳӣ дар растаниҳои дигарро пайдо кунед, ки ба фаҳмиши беҳтар миқёси обдиҳӣ кӯмак мекунад.</p>\n<p>Инчунин, барои раҳоҳое, ки дар ҳамсоягии бо чери парҳез карда мешаванд, масалан чучуқа ё мурчубада, идоракунии зичии парҳиз таъсири мустақиме бар равони ҳаво ва кам шудани занбӯрҳои сурх дорад. Таҳқиқот дар бораи миқдори бӯҳаҳои чучуқа дар ҳектар ба шумо кӯмак мекунад, ки зичии мувофиқро барои кам шудани намӣ ва зиёд шудани гардиши ҳаво дар боғҳои омехта ҳисоб кунед.</p>\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n<h3>Оё орошавии қатрагӣ боиси ҷамъ шудан намак дар атрофи кабудии чери мегардад?</h3>\n<p>Бале, агар шустани намакҳо дар охирӣ-и палси орошавӣ сурат нагирад, ҷамъ шудани намакҳо (Salinity) дар минтақаи решаҳо ба вуҷуд меояд, ки метавонад боиси зарар расонидан бар баргҳо ва заиф шудани раҳ мекунad. Ҳамеша 10 то 20 дарсади ҳажми орошавиро барои шустани намакҳо дар назар доред.</p>\n<h3>Фарқияти лентатип ва қатрагони ҷудо дар идоракунии бемории чери чӣ аст?</h3>\n<p>Лентатип нақши намии баробартар месозад ва аз ба вуҷуд омадани нуқтаҳои хушк ва тобдор пешгирӣ мекунад, ки барои рушди баробари решаҳои чери муҳим аст. Қатрагонҳои ҷудо метавонанд боиси ба вуҷуд омадани минтақаҳои намнок ва хушк шаванд, ки дар сарҳади ин ду минтақа занбӯрҳои сурх фаъолтаранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-جعفری-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های جعفری با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation чери</figcaption></figure>\n<h3>Оё тавассути орошавии қатрагӣ ба таври мустақим ба решаҳо метавон ғарчаро пешгирӣ кард?</h3>\n<p>Обувонишудани маводи мустақим ба решаҳо (Subsurface Drip Irrigation - SDI) як усули хеле самаранок барои кам кардани бемориҳои сатҳӣ мебошад, зеро намии сатҳи хокро ба ҳадди ақал меорад. Ин усул барои кимиҳои баъзе навъҳо монанди тароб метавонад мушкилоти насбкунӣ дошта бошад, вале барои боғҳои калон бо арзиши баланд тавсия дода мешавад.</p>\n\n<h2>Хулоса</h2>\n<p>Идоракунии <strong>Кашотони ва бемориҳои кими дар UVQ</strong> Як сарчашмаи фаъол аст, на танҳо як системаи UVQ. Бо идоракунии дақиқи намӣ, кам кардани тамоси об бо гардан ва эҷоди шароити но муносиб барои афзоиши занҷирҳо дар сатҳи хок, шумо метавонед вобастагӣ ба моддаҳои токсикиро кам кунед. Фаромӯш накунед, ки ҳар системаи UVQ бояд мувофиқи хок ва шароити ҳавоӣ танзим карда шавад. Барои ошноии бо принсипҳои умумии UVQ-и ҳаррӯза ва таъсири мусбати он бар гиёҳ, шумо метавонед мақолаи "Ангуштории UVQ чист ва хусусиятҳои он" (барои муқоиса бо усули анъанавӣ)-ро омӯзед. Дар натиҷа, муваффақият дар парҳези кимиҳои сабз ва саломат, натиҷаи омехтаи хурдуки сифатнок, насби дурусти навори UVQ ва назорати мунтазами кашотон аст.</p>\n<p><strong>Мақолаҳои алоқаманд:</strong> <a href="https://navar-abyari.ir/basil-harvest-yield-per-hectare-guide/">basil harvest yield per hectare guide</a></p>','Дарёмудории зарароварҳо ва бемориҳои каду чунҷорӣ дар системҳои обёрӣ барои чорво','Бигзор, ки тағйирёбии намнокии ҳаво яке аз сабабҳои асосии пайдошавии бемории занбӯрундагӣ ва бактериявӣ дар петрушка мебошад. Бо ёри равонаи қатрагӣ ва системаи нӯгӣ (мундҳо) шумо метавонед даврони ин зараррасониҳоро шикаста даромаддиҳии солимтарро таъмин кунед.','publish','closed','closed','zararovorhoi-kaduchunor-obori',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
